import subprocess, os, pathlib, sys, shutil
ROOT='/tmp/test2'
def run(args, inp=None, files=None, term='xterm', cwd=ROOT, timeout=4, extra_env=None):
    # clean
    if os.path.exists(ROOT):
        shutil.rmtree(ROOT)
    os.makedirs(ROOT, exist_ok=True)
    if files:
        for name, data in files.items():
            p=pathlib.Path(ROOT, name)
            p.parent.mkdir(parents=True, exist_ok=True)
            if isinstance(data, bytes):
                p.write_bytes(data)
            else:
                p.write_text(data)
    env=dict(os.environ); 
    if term is None:
        env.pop('TERM',None)
    else:
        env['TERM']=term
    if extra_env: env.update(extra_env)
    try:
        r=subprocess.run(['/workspace/executable']+args, input=inp, capture_output=True, cwd=cwd, env=env, timeout=timeout)
        print("args",args,"inp",inp,"rc",r.returncode)
        print(" out",r.stdout)
        print(" err",r.stderr)
    except subprocess.TimeoutExpired as e:
        print("args",args,"TIMEOUT out", (e.stdout or b'')[:1000], "err", (e.stderr or b'')[:500])
    if files:
        for name in files:
            p=pathlib.Path(ROOT,name)
            print(f" file {name}=", p.read_bytes() if p.exists() else b'<missing>')
    # list all files recursively
    for p in sorted(pathlib.Path(ROOT).rglob('*')):
        if p.is_file():
            rel=p.relative_to(ROOT)
            if not files or str(rel) not in files:
                print(" extra file", rel, p.read_bytes()[:200])
PY
