import subprocess, os, pathlib, shutil
def test(byte):
    shutil.rmtree('/tmp/test2', ignore_errors=True); os.makedirs('/tmp/test2')
    pathlib.Path('/tmp/test2/a.txt').write_text("hello\n")
    env=dict(os.environ); env['TERM']='xterm'
    inp=bytes([byte])+b'n'
    try:
        r=subprocess.run(['/workspace/executable','--no-color','hello','HELLO','a.txt'], input=inp, capture_output=True, cwd='/tmp/test2', env=env, timeout=2)
    except subprocess.TimeoutExpired as e:
        return (byte,"TIMEOUT")
    prompts=r.stdout.count(b'Replace keyword?')
    replaced=pathlib.Path('/tmp/test2/a.txt').read_bytes()==b'HELLO\n'
    # extract displayed chars after prompt
    return (byte,prompts,replaced, r.stdout)
results={}
for b in range(32,256):
    if b==27: continue
    t=test(b)
    if t[1]=="TIMEOUT":
        results.setdefault("TIMEOUT",[]).append(b); continue
    _,p,rep,_=t
    if p==1 and rep: k="YES/ALL"
    elif p==1 and not rep: k="NO/QUIT"
    elif p==2: k="INVALID"
    else: k=f"other p={p} rep={rep}"
    results.setdefault(k,[]).append(b)
for k,v in results.items():
    print(k, v)
    print([bytes([x]) for x in v])
PY"}

