// ---------------------------------------------------------------------------
// terminfo based terminal (stdout / stderr)
// ---------------------------------------------------------------------------

const COL_RED: u16 = 9;
const COL_GREEN: u16 = 10;
const COL_YELLOW: u16 = 11;
const COL_CYAN: u16 = 14;
const COL_WHITE: u16 = 7;

#[derive(Clone)]
struct TermDb {
    db: Arc<terminfo::Database>,
}

impl TermDb {
    fn from_env() -> Option<Self> {
        match terminfo::Database::from_env() {
            Ok(db) => Some(TermDb { db: Arc::new(db) }),
            Err(_) => None,
        }
    }
    fn max_colors(&self) -> Option<i32> {
        self.db.get::<terminfo::capability::MaxColors>().map(|c| c.0)
    }
    fn fg_bytes(&self, color: u16) -> Option<Vec<u8>> {
        let adjusted: u16 = if color >= 8 {
            match self.max_colors() {
                Some(n) if n >= 256 => color,
                _ => color - 8,
            }
        } else {
            color
        };
        if let Some(cap) = self.db.get::<terminfo::capability::SetAForeground>() {
            return cap.expand().parameters(adjusted as u8).to_vec().ok();
        }
        if let Some(cap) = self.db.get::<terminfo::capability::SetForeground>() {
            let mapped = ((adjusted & 1) << 2) | (adjusted & 2) | ((adjusted & 4) >> 2);
            return cap.expand().parameters(mapped as u8).to_vec().ok();
        }
        None
    }
    fn reset_bytes(&self) -> Option<Vec<u8>> {
        let cap = self.db.get::<terminfo::capability::ExitAttributeMode>()?;
        cap.expand().to_vec().ok()
    }
    fn fg_supported(&self, color: u16) -> bool {
        self.fg_bytes(color).is_some()
    }
}

struct TermStream {
    db: TermDb,
    file: fs::File,
    cur_fg: Option<u16>,
}

impl TermStream {
    fn new(db: TermDb, fd: i32) -> Self {
        let file = unsafe { fs::File::from_raw_fd(fd) };
        TermStream { db, file, cur_fg: None }
    }
    fn write(&mut self, bytes: &[u8]) -> io::Result<()> {
        self.file.write_all(bytes)
    }
    fn write_str(&mut self, s: &str) -> io::Result<()> {
        self.write(s.as_bytes())
    }
    fn flush(&mut self) {
        let _ = self.file.flush();
    }
    fn fg(&mut self, color: u16) -> Result<(), ()> {
        if self.cur_fg == Some(color) {
            return Ok(());
        }
        match self.db.fg_bytes(color) {
            Some(bytes) => {
                if self.write(&bytes).is_err() {
                    return Err(());
                }
                self.cur_fg = Some(color);
                Ok(())
            }
            None => Err(()),
        }
    }
    fn reset(&mut self) -> Result<(), ()> {
        match self.db.reset_bytes() {
            Some(bytes) => {
                let _ = self.write(&bytes);
                self.cur_fg = None;
                Ok(())
            }
            None => Err(()),
        }
    }
}

