    color: bool,
    file: bool,
    skip_vcs: bool,
    skip_gitignore: bool,
    fixed_order: bool,
    parent_ignore: bool,
    line_by_match: bool,
}

impl Default for Settings {
    fn default() -> Self {
        Settings {
            regex: false,
            column: false,
            row: false,
            binary: false,
            statistics: false,
            skipped: false,
            preserve_time: false,
