}

impl Settings {
    fn get(&self, id: SettingId) -> bool {
        use SettingId::*;
        match id {
            Regex => self.regex,
            Column => self.column,
            Row => self.row,
            Binary => self.binary,
            Statistics => self.statistics,
            Skipped => self.skipped,
            PreserveTime => self.preserve_time,
            Interactive => self.interactive,
            Recursive => self.recursive,
            Symlink => self.symlink,
            Color => self.color,
            File => self.file,
            SkipVcs => self.skip_vcs,
            SkipGitignore => self.skip_gitignore,
            FixedOrder => self.fixed_order,
            ParentIgnore => self.parent_ignore,
        }
    }
    fn set(&mut self, id: SettingId, v: bool) {
        use SettingId::*;
        match id {
            Regex => self.regex = v,
            Column => self.column = v,
            Row => self.row = v,
            Binary => self.binary = v,
            Statistics => self.statistics = v,
            Skipped => self.skipped = v,
            PreserveTime => self.preserve_time = v,
            Interactive => self.interactive = v,
            Recursive => self.recursive = v,
            Symlink => self.symlink = v,
            Color => self.color = v,
            File => self.file = v,
            SkipVcs => self.skip_vcs = v,
            SkipGitignore => self.skip_gitignore = v,
            FixedOrder => self.fixed_order = v,
            ParentIgnore => self.parent_ignore = v,
        }
    }
    fn config_key(id: SettingId) -> &'static str {
        use SettingId::*;
        match id {
            Regex => "regex",
            Column => "column",
            Row => "row",
            Binary => "binary",
            Statistics => "statistics",
            Skipped => "skipped",
            PreserveTime => "preserve_time",
            Interactive => "interactive",
            Recursive => "recursive",
            Symlink => "symlink",
            Color => "color",
            File => "file",
            SkipVcs => "skip_vcs",
            SkipGitignore => "skip_gitignore",
            FixedOrder => "fixed_order",
            ParentIgnore => "parent_ignore",
        }
    }
}

fn all_setting_ids() -> [SettingId; 16] {
    use SettingId::*;
    [
        Regex, Column, Row, Binary, Statistics, Skipped, PreserveTime, Interactive, Recursive,
        Symlink, Color, File, SkipVcs, SkipGitignore, FixedOrder, ParentIgnore,
    ]
}

fn home_dir() -> Option<PathBuf> {
    if let Some(h) = env::var_os("HOME") {
        if !h.is_empty() {
            return Some(PathBuf::from(h));
        }
    }
    unsafe {
        let pw = libc::getpwuid(libc::getuid());
        if !pw.is_null() && !(*pw).pw_dir.is_null() {
            let cstr = std::ffi::CStr::from_ptr((*pw).pw_dir);
            return Some(PathBuf::from(cstr.to_string_lossy().into_owned()));
        }
    }
    None
}

fn config_dir() -> Option<PathBuf> {
    if let Some(x) = env::var_os("XDG_CONFIG_HOME") {
        if !x.is_empty() {
            let p = PathBuf::from(&x);
            if p.is_absolute() {
                return Some(p);
            }
        }
    }
    home_dir().map(|h| h.join(".config"))
}

fn parse_config_text(text: &str) -> Option<Settings> {
    let mut settings = Settings::default();
    let mut seen_keys: HashSet<String> = HashSet::new();
    for raw_line in text.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') {
            return None;
        }
        let eq = line.find('=')?;
        let mut key = line[..eq].trim().to_string();
        if (key.starts_with('"') && key.ends_with('"') && key.len() >= 2)
            || (key.starts_with('\'') && key.ends_with('\'') && key.len() >= 2)
        {
            key = key[1..key.len() - 1].to_string();
        }
        if key.is_empty() || !seen_keys.insert(key.clone()) {
            return None;
        }
        let mut value_str = line[eq + 1..].trim();
        // recognise the boolean for known keys; tolerate a trailing comment
        let first_token = value_str.split_whitespace().next().unwrap_or("");
        let bool_val: Option<bool> = match first_token {
            "true" => Some(true),
            "false" => Some(false),
            _ => None,
        };
        // Also allow `true # comment` (split_whitespace already handles) and
        // values that end right at a comment marker.
        let value_no_comment = match value_str.find('#') {
            Some(idx) => value_str[..idx].trim(),
            None => value_str,
        };
        let bool_exact: Option<bool> = match value_no_comment {
            "true" => Some(true),
            "false" => Some(false),
            _ => bool_val.filter(|_| {
                // only accept if the remainder is comment/empty
                let rest = value_str[first_token.len()..].trim();
                rest.is_empty() || rest.starts_with('#')
            }),
        };
        let _ = &mut value_str;
        if let Some(id) = all_setting_ids()
            .iter()
            .find(|id| Settings::config_key(**id) == key)
        {
            match bool_exact {
                Some(v) => settings.set(*id, v),
                None => return None,
            }
        } else if key == "line_by_match" {
            match bool_exact {
                Some(v) => settings.line_by_match = v,
                None => return None,
            }
        } else {
            // unknown key: the value must at least be present
            if value_str.is_empty() {
                return None;
            }
        }
    }
    Some(settings)
}

fn load_config() -> Settings {
    let mut candidates: Vec<PathBuf> = Vec::new();
    if let Some(home) = home_dir() {
        candidates.push(home.join(".ambr.toml"));
    }
    if let Some(mut cd) = config_dir() {
        cd.push("amber");
        cd.push("ambr.toml");
