// ---------------------------------------------------------------------------
// .gitignore handling
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
struct IgnorePattern {
    negated: bool,
    dir_only: bool,
    anchored: bool,
    segments: Vec<String>,
    valid: bool,
}

#[derive(Clone, Debug)]
struct GitIgnore {
    // Lexically-normalised absolute directory that owns the patterns.
    root_abs: PathBuf,
    patterns: Vec<IgnorePattern>,
}

fn lexical_abs(path: &Path) -> PathBuf {
    let abs = if path.is_absolute() {
        path.to_path_buf()
    } else {
        env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("/"))
            .join(path)
    };
    let mut out = PathBuf::new();
    for comp in abs.components() {
        match comp {
            Component::RootDir => out.push("/"),
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
            }
            Component::Normal(c) => out.push(c),
            Component::Prefix(p) => out.push(p.as_os_str()),
        }
    }
    out
}

fn parse_ignore_line(raw: &str) -> Option<IgnorePattern> {
    let mut line = raw.to_string();
    if line.ends_with('\r') {
        line.pop();
    }
    if line.is_empty() {
        return None;
    }
    if line.starts_with('#') {
        return None;
    }
    // Trailing spaces are ignored unless backslash-escaped.
    loop {
        if line.ends_with(' ') {
            let bytes = line.as_bytes();
            let mut backslashes = 0usize;
            let mut i = bytes.len() - 1;
            while i > 0 && bytes[i - 1] == b'\\' {
                backslashes += 1;
                i -= 1;
            }
            if backslashes % 2 == 1 {
                // escaped space: drop the backslash, keep the space
                let mut chars: Vec<char> = line.chars().collect();
                chars.remove(chars.len() - 2);
                line = chars.into_iter().collect();
                break;
            } else {
                line.pop();
            }
        } else {
            break;
        }
    }
    if line.is_empty() {
        return None;
    }
    let mut negated = false;
    if line.starts_with('!') {
        negated = true;
        line = line[1..].to_string();
    } else if line.starts_with("\\!") || line.starts_with("\\#") {
        line = line[1..].to_string();
    }
    if line.is_empty() {
        return None;
