                if ti >= t.len() {
                    return false;
                }
                let mut j = pi + 1;
                let mut neg = false;
                if j < p.len() && (p[j] == '!' || p[j] == '^') {
                    neg = true;
                    j += 1;
                }
                let mut matched = false;
                let mut first = true;
                let ch = t[ti];
                while j < p.len() && (p[j] != ']' || first) {
                    first = false;
                    if p[j] == '\\' && j + 1 < p.len() {
                        if ch == p[j + 1] {
                            matched = true;
                        }
                        j += 2;
                        continue;
                    }
                    if j + 2 < p.len() && p[j + 1] == '-' && p[j + 2] != ']' {
                        if p[j] <= ch && ch <= p[j + 2] {
                            matched = true;
                        }
                        j += 3;
                        continue;
                    }
                    if ch == p[j] {
                        matched = true;
                    }
                    j += 1;
                }
                if j >= p.len() {
                    return false;
                }
                if matched == neg {
                    return false;
                }
                pi = j + 1;
                ti += 1;
            }
            c => {
                if ti >= t.len() || t[ti] != c {
                    return false;
                }
                pi += 1;
                ti += 1;
            }
        }
    }
    ti == t.len()
}

fn segments_match(pat: &[String], path: &[String]) -> bool {
    if pat.is_empty() {
        return path.is_empty();
    }
    if pat[0] == "**" {
        // `**` matches zero or more whole segments. A trailing `**`
        // requires at least the directory itself to have been matched by
        // the caller; here zero segments is allowed for patterns such as
        // `**/a.txt`.
        for skip in 0..=path.len() {
            if segments_match(&pat[1..], &path[skip..]) {
                return true;
            }
        }
        return false;
    }
    if path.is_empty() {
        return false;
    }
    // `a/**` style: handled by the `**` branch when reached.
    if !glob_segment_match(&pat[0], &path[0]) {
        return false;
    }
    segments_match(&pat[1..], &path[1..])
}

impl GitIgnore {
    fn load(dir_path: &Path, gitignore_file: &Path) -> GitIgnore {
        let mut patterns = Vec::new();
        if let Ok(bytes) = fs::read(gitignore_file) {
            let text = String::from_utf8_lossy(&bytes);
            for line in text.lines() {
                if let Some(p) = parse_ignore_line(line) {
                    if p.valid {
                        patterns.push(p);
                    }
                }
            }
        }
        GitIgnore {
            root_abs: lexical_abs(dir_path),
            patterns,
        }
    }
    fn empty(dir_path: &Path) -> GitIgnore {
        GitIgnore {
            root_abs: lexical_abs(dir_path),
            patterns: Vec::new(),
        }
    }
    fn is_ignored(&self, target: &Path, is_dir: bool) -> bool {
        let target_abs = lexical_abs(target);
        let rel = match target_abs.strip_prefix(&self.root_abs) {
            Ok(r) => r.to_path_buf(),
            Err(_) => return false,
        };
        if rel.as_os_str().is_empty() {
            return false;
        }
        let rel_segments: Vec<String> = rel
            .components()
            .map(|c| c.as_os_str().to_string_lossy().into_owned())
            .collect();
        let basename = rel_segments.last().cloned().unwrap_or_default();
        let mut ignored = false;
        for pat in &self.patterns {
            if !pat.valid {
                continue;
            }
            if pat.dir_only && !is_dir {
                continue;
            }
            let matched = if pat.anchored {
                segments_match(&pat.segments, &rel_segments)
            } else {
                // no slash: match the basename
                pat.segments.len() == 1 && glob_segment_match(&pat.segments[0], &basename)
            };
            if matched {
                ignored = !pat.negated;
            }
        }
        ignored
    }
}
RS
"}

