#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
enum OptId {
    MaxThreads,
    SizePerThread,
    BinCheckBytes,
    MmapBytes,
}

fn opt_spec(id: OptId) -> (&'static str, &'static str) {
