        OptId::SizePerThread => ("size-per-thread", "BYTES"),
        OptId::BinCheckBytes => ("bin-check-bytes", "BYTES"),
        OptId::MmapBytes => ("mmap-bytes", "BYTES"),
    }
}

fn opt_token(id: OptId) -> String {
    let (name, meta) = opt_spec(id);
    format!("--{} <{}>", name, meta)
}

// (id, positive long, negative long, help-form-is-positive)
fn setting_specs() -> Vec<(SettingId, &'static str, &'static str, bool)> {
    use SettingId::*;
    vec![
        (Regex, "regex", "no-regex", true),
        (Column, "column", "no-column", true),
        (Row, "row", "no-row", true),
        (Binary, "binary", "no-binary", true),
        (Statistics, "statistics", "no-statistics", true),
        (Skipped, "skipped", "no-skipped", true),
        (PreserveTime, "preserve-time", "no-preserve-time", true),
        (Interactive, "interactive", "no-interactive", false),
        (Recursive, "recursive", "no-recursive", false),
        (Symlink, "symlink", "no-symlink", false),
        (Color, "color", "no-color", false),
        (File, "file", "no-file", false),
        (SkipVcs, "skip-vcs", "no-skip-vcs", false),
        (SkipGitignore, "skip-gitignore", "no-skip-gitignore", false),
        (FixedOrder, "fixed-order", "no-fixed-order", false),
        (ParentIgnore, "parent-ignore", "no-parent-ignore", false),
    ]
}

#[derive(Clone, Debug)]
enum LongKind {
    SettingPos(SettingId),
    SettingNeg(SettingId),
    Simple(&'static str),
    Help,
    Version,
    Opt(OptId),
}

fn long_map() -> HashMap<String, LongKind> {
    let mut m = HashMap::new();
    for (id, pos, neg, _) in setting_specs() {
        m.insert(pos.to_string(), LongKind::SettingPos(id));
        m.insert(neg.to_string(), LongKind::SettingNeg(id));
    }
    for s in ["key-from-file", "rep-from-file", "verbose", "tbm", "sse"] {
        m.insert(s.to_string(), LongKind::Simple(s));
    }
    m.insert("help".to_string(), LongKind::Help);
    m.insert("version".to_string(), LongKind::Version);
    for id in [
        OptId::MaxThreads,
        OptId::SizePerThread,
        OptId::BinCheckBytes,
        OptId::MmapBytes,
    ] {
        m.insert(opt_spec(id).0.to_string(), LongKind::Opt(id));
    }
