}

fn token_display_for_long(name: &str, kind: &LongKind) -> String {
    match kind {
        LongKind::Opt(id) => opt_token(*id),
        _ => format!("--{}", name),
    }
}

struct InvalidEvent {
    index: usize,
    opt: OptId,
    message: String,
}

struct DuplicateEvent {
    index: usize,
    name: String,
    kind: LongKind,
}

struct Parsed {
    keyword: String,
    replacement: String,
    paths: Vec<PathBuf>,
    // long name -> count
    counts: HashMap<String, usize>,
    simple: HashSet<&'static str>,
    opt_values: HashMap<OptId, Option<String>>,
}

impl Parsed {
    fn opt_usize(&self, id: OptId, default: usize) -> usize {
        match self.opt_values.get(&id) {
            Some(Some(v)) => v.parse::<usize>().unwrap_or(default),
            _ => default,
        }
    }
}

enum ParseOutcome {
    Run(Box<Parsed>),
    Exit(i32),
}

struct Parser {
    bin: String,
    longs: HashMap<String, LongKind>,
    // long name -> token display, ordered by long name
    seen_tokens: BTreeMap<String, String>,
    counts: HashMap<String, Vec<usize>>,
    invalid_events: Vec<InvalidEvent>,
    duplicate_events: Vec<DuplicateEvent>,
}

impl Parser {
    fn new(bin: String) -> Self {
        Parser {
            bin,
            longs: long_map(),
            seen_tokens: BTreeMap::new(),
            counts: HashMap::new(),
            invalid_events: Vec::new(),
            duplicate_events: Vec::new(),
        }
    }

    fn record(&mut self, name: &str, kind: &LongKind, index: usize) {
        self.seen_tokens
            .insert(name.to_string(), token_display_for_long(name, kind));
        let v = self.counts.entry(name.to_string()).or_default();
        v.push(index);
        if v.len() == 2 {
            self.duplicate_events.push(DuplicateEvent {
                index,
                name: name.to_string(),
                kind: kind.clone(),
            });
        }
    }

    fn full_usage(&self) -> String {
        format!(
            "{} [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...",
            self.bin
        )
    }

    fn short_usage(&self, tokens: &BTreeMap<String, String>) -> String {
        if tokens.is_empty() {
            format!("{} <KEYWORD> <REPLACEMENT>", self.bin)
        } else {
            let list: Vec<String> = tokens.values().cloned().collect();
            format!("{} <KEYWORD> <REPLACEMENT> {}", self.bin, list.join(" "))
        }
    }

    fn print_help(&self) -> ParseOutcome {
        let text = HELP_BODY.replace("{BIN}", &self.bin);
        write_fd(1, text.as_bytes());
        ParseOutcome::Exit(0)
    }

    fn print_version(&self) -> ParseOutcome {
        write_fd(1, b"ambr 0.6.0\n");
        ParseOutcome::Exit(0)
    }

    fn err_exit(&self, msg: &str) -> ParseOutcome {
        write_fd(2, msg.as_bytes());
        ParseOutcome::Exit(1)
    }

    fn unknown_error(&self, display: &str, name_for_suggestion: Option<&str>) -> ParseOutcome {
        let mut suggestion: Option<(String, String)> = None;
        if let Some(name) = name_for_suggestion {
            let mut best: Option<(f64, String)> = None;
            for cand in self.longs.keys() {
                let conf = jaro_winkler(name, cand);
                if conf > 0.8 {
                    match &best {
                        Some((bconf, _)) if *bconf >= conf => {}
                        _ => best = Some((conf, cand.clone())),
                    }
                }
            }
            if let Some((_, cand)) = best {
                let kind = self.longs.get(&cand).cloned().unwrap();
                suggestion = Some((cand.clone(), token_display_for_long(&cand, &kind)));
            }
        }
        let mut first = format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
            display
        );
        let usage = if self.seen_tokens.is_empty() && suggestion.is_none() {
            self.full_usage()
        } else {
            let mut tokens = self.seen_tokens.clone();
            if let Some((cand, disp)) = &suggestion {
                tokens.insert(cand.clone(), disp.clone());
            }
            self.short_usage(&tokens)
        };
        if let Some((cand, _)) = &suggestion {
            first.push_str(&format!(
                "\tDid you mean \u{1b}[32m--\u{1b}[0m\u{1b}[32m{}\u{1b}[0m?\n",
                cand
            ));
        }
        let msg = format!(
            "{}\nUSAGE:\n    {}\n\nFor more information try --help\n",
            first, usage
        );
        self.err_exit(&msg)
    }

    fn missing_error(&self, positional: &[String]) -> ParseOutcome {
        let mut missing: Vec<&str> = Vec::new();
        if positional.is_empty() {
            missing.push("<KEYWORD>");
        }
        if positional.len() < 2 {
            missing.push("<REPLACEMENT>");
        }
        let mut tokens = self.seen_tokens.clone();
        for id in [
            OptId::MaxThreads,
            OptId::SizePerThread,
            OptId::BinCheckBytes,
            OptId::MmapBytes,
        ] {
            tokens.insert(opt_spec(id).0.to_string(), opt_token(id));
        }
        let mut msg = String::from("error: The following required arguments were not provided:\n");
        for m in &missing {
            msg.push_str(&format!("    {}\n", m));
        }
        msg.push_str(&format!(
            "\nUSAGE:\n    {}\n\nFor more information try --help\n",
            self.short_usage(&tokens)
        ));
        self.err_exit(&msg)
    }

    fn duplicate_error(&self, dup: &DuplicateEvent) -> ParseOutcome {
        let mut tokens = self.seen_tokens.clone();
        for id in [
            OptId::MaxThreads,
            OptId::SizePerThread,
            OptId::BinCheckBytes,
            OptId::MmapBytes,
        ] {
            tokens.insert(opt_spec(id).0.to_string(), opt_token(id));
        }
        let shown = token_display_for_long(&dup.name, &dup.kind);
        let msg = format!(
            "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
            shown,
            self.short_usage(&tokens)
        );
        self.err_exit(&msg)
    }

    fn parse(&mut self, args: &[String]) -> ParseOutcome {
        let mut positional: Vec<String> = Vec::new();
        let mut simple: HashSet<&'static str> = HashSet::new();
        let mut opt_values: HashMap<OptId, Option<String>> = HashMap::new();
        let mut after_sep = false;
        let mut i = 0usize;
        while i < args.len() {
            let token = &args[i];
            let idx = i;
            i += 1;
            if after_sep {
                positional.push(token.clone());
                continue;
            }
            if token == "--" {
                after_sep = true;
                continue;
            }
            if token.starts_with("---") {
                return self.unknown_error("--", None);
            }
            if let Some(rest) = token.strip_prefix("--") {
                if rest.len() > 0 {
                    let (name, eq_value) = match rest.find('=') {
                        Some(p) => (&rest[..p], Some(rest[p + 1..].to_string())),
                        None => (rest, None),
                    };
                    let kind = match self.longs.get(name) {
                        Some(k) => k.clone(),
                        None => {
                            return self.unknown_error(
                                &format!("--{}", name),
                                Some(name),
                            )
                        }
                    };
                    match kind {
                        LongKind::Help => return self.print_help(),
                        LongKind::Version => return self.print_version(),
                        LongKind::Simple(s) => {
                            self.record(name, &kind, idx);
                            simple.insert(s);
                        }
                        LongKind::SettingPos(_) | LongKind::SettingNeg(_) => {
                            self.record(name, &kind, idx);
                        }
                        LongKind::Opt(oid) => {
                            self.record(name, &kind, idx);
                            let value: Option<String> = if let Some(v) = eq_value {
                                Some(v)
                            } else if i < args.len() {
                                let next = &args[i];
                                let looks_like_flag =
                                    next.len() > 1 && next.starts_with('-');
                                if looks_like_flag {
                                    None
                                } else {
                                    i += 1;
                                    Some(next.clone())
                                }
                            } else {
                                None
                            };
                            if let Some(v) = &value {
                                if let Err(e) = v.parse::<usize>() {
                                    self.invalid_events.push(InvalidEvent {
                                        index: idx,
                                        opt: oid,
                                        message: e.to_string(),
                                    });
                                }
                            }
                            opt_values.insert(oid, value);
                        }
                    }
                    continue;
                }
            }
            if token.len() > 1 && token.starts_with('-') {
                // short bundle
                let chars: Vec<char> = token[1..].chars().collect();
                let mut consumed_help_or_version: Option<ParseOutcome> = None;
                for ch in &chars {
                    match ch {
                        'h' => {
                            consumed_help_or_version = Some(self.print_help());
                            break;
                        }
                        'V' => {
                            consumed_help_or_version = Some(self.print_version());
                            break;
                        }
                        'r' => {
                            let kind = LongKind::SettingPos(SettingId::Regex);
                            self.record("regex", &kind, idx);
                        }
                        other => {
                            return self.unknown_error(&format!("-{}", other), None);
                        }
                    }
                }
                if let Some(out) = consumed_help_or_version {
                    return out;
                }
                continue;
            }
            positional.push(token.clone());
        }

        if positional.len() < 2 {
            return self.missing_error(&positional);
        }

        // Earliest validation event (duplicate or invalid value) wins.
        let first_dup = self.duplicate_events.iter().min_by_key(|e| e.index);
        let first_inv = self.invalid_events.iter().min_by_key(|e| e.index);
        match (first_dup, first_inv) {
            (Some(d), Some(v)) => {
                if v.index < d.index {
                    let msg = format!(
                        "error: Invalid value for '{}': {}\n",
                        opt_token(v.opt),
                        v.message
                    );
                    return self.err_exit(&msg);
                } else {
                    return self.duplicate_error(d);
                }
            }
            (Some(d), None) => return self.duplicate_error(d),
            (None, Some(v)) => {
                let msg = format!(
                    "error: Invalid value for '{}': {}\n",
                    opt_token(v.opt),
                    v.message
                );
                return self.err_exit(&msg);
            }
            _ => {}
        }

        let counts: HashMap<String, usize> = self
            .counts
            .iter()
            .map(|(k, v)| (k.clone(), v.len()))
            .collect();
        ParseOutcome::Run(Box::new(Parsed {
            keyword: positional[0].clone(),
            replacement: positional[1].clone(),
            paths: positional[2..].iter().map(PathBuf::from).collect(),
            counts,
            simple,
            opt_values,
        }))
    }
}
RS
"}

