// ---------------------------------------------------------------------------
// Interactive input
// ---------------------------------------------------------------------------

struct InputReader;

impl InputReader {
    fn read_one(&mut self) -> u8 {
        let is_tty = unsafe { libc::isatty(0) } == 1;
        let mut orig: libc::termios = unsafe { std::mem::zeroed() };
        let have_termios =
            is_tty && unsafe { libc::tcgetattr(0, &mut orig) } == 0;
        if have_termios {
            let mut raw = orig;
            raw.c_lflag &= !(libc::ICANON | libc::ECHO);
            unsafe { libc::tcsetattr(0, libc::TCSANOW, &raw) };
        }
        let mut buf = [0u8; 1];
        let n = io::stdin().read(&mut buf).unwrap_or(0);
        if have_termios {
            unsafe { libc::tcsetattr(0, libc::TCSANOW, &orig) };
        }
        if n == 1 {
            buf[0]
        } else {
            0
        }
    }

    fn read_answer_char(&mut self) -> char {
        loop {
            let b = self.read_one();
            if b != 0x1b {
                return b as char;
            }
            let b2 = self.read_one();
            match b2 {
                b'[' => {
                    // Consume a CSI sequence up to its final byte.
                    let mut final_byte = 0u8;
                    loop {
                        let c = self.read_one();
                        if c == 0 {
                            return '\0';
                        }
                        if (0x40..=0x7e).contains(&c) {
                            final_byte = c;
                            break;
                        }
                    }
                    if final_byte == b'~' {
                        return '\0';
                    }
                    continue;
                }
                b'O' => continue,
                0x1b => continue,
                _ => return '\0',
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Application
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq)]
enum Flow {
    Continue,
    Quit,
    Fatal,
}

struct Message {
    color: u16,
    text: String,
}

struct MatchInfo {
    start: usize,
    end: usize,
    replacement: Vec<u8>,
}

enum Task {
    File(PathBuf, Option<GitIgnore>),
    Dir(PathBuf, Option<GitIgnore>),
    None,
}

struct App {
    out: TermStream,
    err: TermStream,
    settings: Settings,
    tbm: bool,
    max_threads: usize,
    size_per_thread: usize,
    bin_check_bytes: usize,
    #[allow(dead_code)]
    mmap_bytes: usize,
    keyword: String,
    replacement: String,
    keyword_bytes: Vec<u8>,
    regex: Option<Regex>,
    messages: Vec<Message>,
    stderr_color_failed: bool,
    all: bool,
    quit: bool,
    reader: InputReader,
    start: Instant,
    find_elapsed: Duration,
    match_elapsed: Duration,
}

impl App {
    fn record(&mut self, color: u16, text: String) {
        if self.settings.color && !self.err.db.fg_supported(color) {
            self.stderr_color_failed = true;
        }
        self.messages.push(Message { color, text });
    }
    fn record_finder_error_str(&mut self, err_text: &str, path: &Path) {
        self.record(
            COL_RED,
            format!("Error: {} @ {}\n", err_text, path.display()),
        );
    }
    fn record_finder_error(&mut self, e: &io::Error, path: &Path) {
        self.record_finder_error_str(&e.to_string(), path);
    }
    fn record_matcher_error(&mut self, e: &io::Error, path: &Path) {
        self.record(
            COL_RED,
            format!("Error: {} @ {:?}\n\n", io_kind_label(e), path),
        );
    }
    fn record_replacer_error(&mut self, e: &io::Error, path: &Path) {
        self.record(
            COL_RED,
            format!("Error: {} @ {:?}\n", io_kind_label(e), path),
        );
    }
    fn record_skip(&mut self, reason: &str, path: &Path) {
        if !self.settings.skipped {
            return;
        }
        let padding = " ".repeat(10usize.saturating_sub(reason.len()));
        self.record(
            COL_CYAN,
            format!("Skip ({}){}: {:?}\n", reason, padding, path),
        );
    }

    fn search_parent(&mut self, path: &Path) -> Option<GitIgnore> {
        if !self.settings.skip_gitignore || !self.settings.parent_ignore {
            return None;
        }
        let md = fs::metadata(path).ok()?;
        let base: PathBuf = if md.is_dir() {
            path.to_path_buf()
        } else {
            path.parent().map(|p| p.to_path_buf()).unwrap_or_default()
        };
        let mut cand = base.join("..");
        loop {
            let gi_path = cand.join(".gitignore");
            if gi_path.exists() {
                let display_path = cand.clone();
                self.record(
                    COL_CYAN,
                    format!(
                        "Found .gitignore at the parent directory: {:?}\n\n",
                        display_path
                    ),
                );
                return Some(GitIgnore::load(&cand, &gi_path));
            }
            match fs::canonicalize(&cand) {
                Ok(c) => {
                    if c.parent().is_none() {
                        break;
                    }
                }
                Err(_) => break,
            }
            cand = cand.join("..");
        }
        None
    }

    fn run(&mut self, paths_arg: &[PathBuf]) -> Flow {
        let paths: Vec<PathBuf> = if paths_arg.is_empty() {
            vec![PathBuf::from(".")]
        } else {
            paths_arg.to_vec()
        };
        let mut tasks: Vec<Task> = Vec::new();
        let mut invalid: Vec<(String, PathBuf)> = Vec::new();
        for path in &paths {
            let parent = self.search_parent(path);
            match fs::metadata(path) {
                Ok(md) if md.is_file() => tasks.push(Task::File(path.clone(), parent)),
                Ok(md) if md.is_dir() => tasks.push(Task::Dir(path.clone(), parent)),
                Ok(_) => {
                    if let Err(e) = fs::read_dir(path) {
                        self.record_finder_error(&e, path);
                    }
                    tasks.push(Task::None);
                }
                Err(e) => {
                    invalid.push((e.to_string(), path.clone()));
                    tasks.push(Task::None);
                }
            }
        }
        for task in tasks {
            let flow = match &task {
                Task::File(p, m) => self.process_candidate(p, m.clone()),
                Task::Dir(p, m) => self.process_dir(p, m.clone()),
                Task::None => Flow::Continue,
            };
            if flow != Flow::Continue {
                return flow;
            }
        }
        for (text, path) in &invalid {
            for _ in 0..2 {
                self.record_finder_error_str(text, path);
            }
        }
        Flow::Continue
    }

    fn process_dir(&mut self, dir_path: &Path, inherited: Option<GitIgnore>) -> Flow {
        let effective: Option<GitIgnore> = if self.settings.skip_gitignore {
            let gi_path = dir_path.join(".gitignore");
            if gi_path.exists() {
                Some(GitIgnore::load(dir_path, &gi_path))
            } else {
                inherited
            }
        } else {
            None
        };
        let find_start = Instant::now();
        let entries: Vec<fs::DirEntry> = match fs::read_dir(dir_path) {
            Ok(rd) => {
                let mut v = Vec::new();
                for item in rd {
                    match item {
                        Ok(e) => v.push(e),
                        Err(e) => self.record_finder_error(&e, dir_path),
                    }
                }
                v
            }
            Err(e) => {
                self.find_elapsed += find_start.elapsed();
                self.record_finder_error(&e, dir_path);
                return Flow::Continue;
            }
        };
        self.find_elapsed += find_start.elapsed();
        for entry in &entries {
            let path = entry.path();
            let file_type = match entry.file_type() {
                Ok(t) => t,
                Err(_) => continue,
            };
            if file_type.is_dir() {
                let mut skipped = false;
                if self.settings.skip_vcs {
                    let name = entry.file_name();
                    if name == ".git" || name == ".hg" || name == ".svn" || name == ".bzr" {
                        self.record_skip("vcs file", &path);
                        skipped = true;
                    }
                }
                if self.settings.skip_gitignore {
                    if let Some(m) = &effective {
                        if m.is_ignored(&path, true) {
                            self.record_skip(".gitignore", &path);
                            skipped = true;
                        }
                    }
                }
                if skipped {
                    continue;
                }
                if self.settings.recursive {
                    let flow = self.process_dir(&path, effective.clone());
                    if flow != Flow::Continue {
                        return flow;
                    }
                }
            } else if file_type.is_file() {
                let flow = self.process_candidate(&path, effective.clone());
                if flow != Flow::Continue {
                    return flow;
                }
            } else if file_type.is_symlink() {
                if let Ok(md) = fs::metadata(&path) {
                    if md.is_file() && self.settings.symlink {
                        let flow = self.process_candidate(&path, effective.clone());
                        if flow != Flow::Continue {
                            return flow;
                        }
                    }
                }
            } else {
                // special files are silently ignored
            }
        }
        Flow::Continue
    }

    fn compute_matches(&mut self, content: &[u8]) -> Vec<MatchInfo> {
        let match_start = Instant::now();
        let mut result = Vec::new();
        if self.settings.regex {
            if let Some(re) = &self.regex {
                if let Ok(text) = std::str::from_utf8(content) {
                    for caps in re.captures_iter(text) {
                        if let Some(m) = caps.get(0) {
                            let mut dst = String::new();
                            caps.expand(&self.replacement, &mut dst);
                            result.push(MatchInfo {
                                start: m.start(),
                                end: m.end(),
                                replacement: dst.into_bytes(),
                            });
                        }
                    }
                }
            }
            self.match_elapsed += match_start.elapsed();
            return result;
        }
        // literal matching
        if self.keyword_bytes.is_empty() {
            if self.tbm {
                self.match_elapsed += match_start.elapsed();
                return result;
            }
            // The default/SSE matchers spin forever on an empty keyword.
            hang_forever();
        }
        let needle = self.keyword_bytes.clone();
        let replacement = self.replacement.clone().into_bytes();
        let mut pos = 0usize;
        while pos + needle.len() <= content.len() {
            match memchr::memmem::find(&content[pos..], &needle) {
                Some(off) => {
                    let s = pos + off;
                    let e = s + needle.len();
                    result.push(MatchInfo {
                        start: s,
                        end: e,
                        replacement: replacement.clone(),
                    });
                    pos = e;
                }
                None => break,
            }
        }
        self.match_elapsed += match_start.elapsed();
        result
    }

    fn process_candidate(&mut self, path: &Path, matcher: Option<GitIgnore>) -> Flow {
        if self.settings.skip_gitignore {
            if let Some(m) = &matcher {
                if m.is_ignored(path, false) {
                    self.record_skip(".gitignore", path);
                    return Flow::Continue;
                }
            }
        }
        let content = match fs::read(path) {
            Ok(c) => c,
            Err(e) => {
                self.record_matcher_error(&e, path);
                return Flow::Continue;
            }
        };
        if !self.settings.binary {
            let check_len = self.bin_check_bytes.min(content.len());
            if content[..check_len].iter().any(|b| *b < 9) {
                self.record_skip("binary", path);
                return Flow::Continue;
            }
        }
        if self.size_per_thread == 0 && !content.is_empty() {
            fake_panic(
                "matcher",
                "src/matcher.rs:190:35",
                "attempt to divide by zero",
            );
        }
        let matches = self.compute_matches(&content);
        if matches.is_empty() {
            return Flow::Continue;
        }
        // In interactive mode a non-UTF-8 path makes the replacer panic
        // before anything is printed (unless "all" is already active).
        if self.settings.interactive && !self.all && path.to_str().is_none() {
            fake_panic(
                "replacer",
                "src/pipeline_replacer.rs:125:57",
                "called `Option::unwrap()` on a `None` value",
            );
        }
        // Create the temporary file used for the replacement.
        let parent_dir: PathBuf = match path.parent() {
            Some(p) if !p.as_os_str().is_empty() => p.to_path_buf(),
            _ => PathBuf::from("."),
        };
        let tmp_path = match create_tmp_file(&parent_dir) {
            Ok(p) => p,
            Err(e) => {
                self.record_replacer_error(&e, path);
                return Flow::Continue;
            }
        };
        // Decide each match.
        let mut accepted: Vec<bool> = vec![false; matches.len()];
        if !self.settings.interactive || self.all {
            for a in accepted.iter_mut() {
                *a = true;
            }
        } else {
            for idx in 0..matches.len() {
                if self.all {
                    accepted[idx] = true;
                    continue;
                }
                if matches[idx].start == content.len() {
                    let _ = fs::remove_file(&tmp_path);
                    fake_panic(
                        "replacer",
                        "src/console.rs:105:16",
                        &format!(
                            "index out of bounds: the len is {} but the index is {}",
                            content.len(),
                            content.len()
                        ),
                    );
                }
                match self.prompt_match(path, &content, &matches[idx]) {
                    Ok(PromptResult::Yes) => accepted[idx] = true,
                    Ok(PromptResult::No) => accepted[idx] = false,
                    Ok(PromptResult::All) => {
                        accepted[idx] = true;
                        self.all = true;
                    }
                    Ok(PromptResult::Quit) => {
                        let _ = fs::remove_file(&tmp_path);
                        self.quit = true;
                        return Flow::Quit;
                    }
                    Err(()) => {
                        // Colour/output failure: leave the temp file behind.
                        return Flow::Fatal;
                    }
                }
            }
        }
        // Build the new content.
        let mut new_content: Vec<u8> = Vec::with_capacity(content.len());
        let mut cursor = 0usize;
        for (idx, m) in matches.iter().enumerate() {
            new_content.extend_from_slice(&content[cursor..m.start]);
            if accepted[idx] {
                new_content.extend_from_slice(&m.replacement);
            } else {
                new_content.extend_from_slice(&content[m.start..m.end]);
            }
            cursor = m.end;
        }
        new_content.extend_from_slice(&content[cursor..]);
        // Write it into the temp file and move it into place.
        if let Err(e) = fs::write(&tmp_path, &new_content) {
            self.record_replacer_error(&e, path);
            let _ = fs::remove_file(&tmp_path);
            return Flow::Continue;
        }
        let metadata = fs::metadata(path).ok();
        if let Some(md) = &metadata {
            let _ = fs::set_permissions(&tmp_path, md.permissions());
            if self.settings.preserve_time {
                set_file_mtime(&tmp_path, md);
            }
        }
        let dest = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
        if let Err(e) = fs::rename(&tmp_path, &dest) {
            self.record_replacer_error(&e, path);
            let _ = fs::remove_file(&tmp_path);
            return Flow::Continue;
        }
        Flow::Continue
    }

    fn prompt_match(
        &mut self,
        path: &Path,
        content: &[u8],
        m: &MatchInfo,
    ) -> Result<PromptResult, ()> {
        self.print_match_lines(path, content, m)?;
        loop {
            if self.settings.color {
                self.out.fg(COL_CYAN)?;
            }
            self.out
                .write_str("Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ")
                .map_err(|_| ())?;
            self.out.flush();
            let c = self.reader.read_answer_char();
            // Echo the answer (term-style `write_line`).
            let s = c.to_string();
            self.out.write(s.as_bytes()).map_err(|_| ())?;
            if !s.ends_with('\n') {
                self.out.write(b"\n").map_err(|_| ())?;
            }
            match c {
                'y' | 'Y' | '\n' | '\r' | ' ' => return Ok(PromptResult::Yes),
                'n' | 'N' => return Ok(PromptResult::No),
                'a' | 'A' => return Ok(PromptResult::All),
                'q' | 'Q' => return Ok(PromptResult::Quit),
                _ => continue,
            }
        }
    }

    fn print_match_lines(
        &mut self,
        path: &Path,
        content: &[u8],
        m: &MatchInfo,
    ) -> Result<(), ()> {
        let (line_no, column, seg_start, seg_end) = line_info(content, m);
        let mut coord = String::new();
        if self.settings.column {
            coord.push_str(&format!("{}:", line_no));
        }
        if self.settings.row {
            coord.push_str(&format!("{}:", column));
        }
        let path_str = path.display().to_string();
        let plain_header = if self.settings.file {
            format!("{}: {}", path_str, coord)
        } else {
            format!("{:<4}", coord)
        };
        let header_width = UnicodeWidthStr::width(plain_header.as_str());
        let arrow_prefix = format!("{}-> ", " ".repeat(header_width.saturating_sub(3)));
        let prefix = &content[seg_start..m.start];
        let matched = &content[m.start..m.end];
        let suffix = &content[m.end..seg_end];

        // Original line.
        if self.settings.color {
            if self.settings.file {
                self.out.fg(COL_GREEN)?;
                self.out.write_str(&path_str).map_err(|_| ())?;
                self.out.fg(COL_CYAN)?;
                self.out
                    .write_str(&format!(": {}", coord))
                    .map_err(|_| ())?;
            } else {
                self.out.fg(COL_CYAN)?;
                self.out.write_str(&plain_header).map_err(|_| ())?;
            }
        } else {
            self.out.write_str(&plain_header).map_err(|_| ())?;
        }
        self.print_segment(prefix, matched, suffix, false)?;
        // Replaced line.
        if self.settings.color {
            self.out.fg(COL_CYAN)?;
        }
        self.out.write_str(&arrow_prefix).map_err(|_| ())?;
        self.print_segment(prefix, &m.replacement, suffix, true)?;
        Ok(())
    }

    fn print_segment(
        &mut self,
        prefix: &[u8],
        middle: &[u8],
        suffix: &[u8],
        _is_replacement: bool,
    ) -> Result<(), ()> {
        if self.settings.color {
            if !prefix.is_empty() {
                self.out.fg(COL_WHITE)?;
                self.out
                    .write(String::from_utf8_lossy(prefix).as_bytes())
                    .map_err(|_| ())?;
            }
            self.out.fg(COL_YELLOW)?;
            self.out
                .write(String::from_utf8_lossy(middle).as_bytes())
                .map_err(|_| ())?;
            self.out.fg(COL_WHITE)?;
            self.out
                .write(String::from_utf8_lossy(suffix).as_bytes())
                .map_err(|_| ())?;
        } else {
            self.out
                .write(String::from_utf8_lossy(prefix).as_bytes())
                .map_err(|_| ())?;
            self.out
                .write(String::from_utf8_lossy(middle).as_bytes())
                .map_err(|_| ())?;
            self.out
                .write(String::from_utf8_lossy(suffix).as_bytes())
                .map_err(|_| ())?;
        }
        self.out.write(b"\n").map_err(|_| ())?;
        Ok(())
    }
}

enum PromptResult {
    Yes,
    No,
    All,
    Quit,
}

fn line_info(content: &[u8], m: &MatchInfo) -> (usize, usize, usize, usize) {
    let s = m.start;
    let line_no = content[..s].iter().filter(|b| **b == b'\n').count() + 1;
    let column = match content[..s].iter().rposition(|b| *b == b'\n') {
        Some(p) => s - p,
        None => s,
    };
    let seg_start = if s < content.len() && (content[s] == b'\n' || content[s] == b'\r') {
        s
    } else {
        let mut start = s;
        while start > 0 && content[start] != b'\n' && content[start] != b'\r' {
            start -= 1;
        }
        if start == 0 {
            0
        } else {
            start + 1
        }
    };
    let mut seg_end = m.end;
    while seg_end < content.len() && content[seg_end] != b'\n' && content[seg_end] != b'\r' {
        seg_end += 1;
    }
    (line_no, column, seg_start, seg_end)
}

fn create_tmp_file(dir: &Path) -> io::Result<PathBuf> {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut last_err: Option<io::Error> = None;
    for _ in 0..200 {
        let mut rnd = [0u8; 6];
        match fs::File::open("/dev/urandom") {
            Ok(mut f) => {
                let _ = f.read_exact(&mut rnd);
            }
            Err(_) => {
                let t = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.as_nanos())
                    .unwrap_or(0);
                for (i, b) in rnd.iter_mut().enumerate() {
                    *b = ((t >> (i * 8)) & 0xff) as u8;
                }
            }
        }
        let suffix: String = rnd
            .iter()
            .map(|b| CHARS[(*b as usize) % CHARS.len()] as char)
            .collect();
        let candidate = dir.join(format!(".tmp{}", suffix));
        match fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&candidate)
        {
            Ok(_) => return Ok(candidate),
            Err(e) => {
                if e.kind() == io::ErrorKind::AlreadyExists {
                    last_err = Some(e);
                    continue;
                }
                return Err(e);
            }
        }
    }
    Err(last_err.unwrap_or_else(|| io::Error::new(io::ErrorKind::Other, "tempfile")))
}

fn set_file_mtime(tmp_path: &Path, metadata: &fs::Metadata) {
    use std::os::unix::ffi::OsStrExt;
    let mtime = metadata.mtime();
    let mtime_nsec = metadata.mtime_nsec();
    let times = [
        libc::timespec {
            tv_sec: 0,
            tv_nsec: libc::UTIME_OMIT as i64,
        },
        libc::timespec {
            tv_sec: mtime as libc::time_t,
            tv_nsec: mtime_nsec as libc::c_long,
        },
    ];
    let cpath = match std::ffi::CString::new(tmp_path.as_os_str().as_bytes()) {
        Ok(c) => c,
        Err(_) => return,
    };
