        tbm,
        max_threads,
        size_per_thread,
        bin_check_bytes,
        mmap_bytes,
        keyword_bytes: keyword.as_bytes().to_vec(),
        keyword,
        replacement,
        regex,
        messages: Vec::new(),
        stderr_color_failed: false,
        all: false,
        quit: false,
        reader: InputReader,
        start: Instant::now(),
        find_elapsed: Duration::from_nanos(0),
        match_elapsed: Duration::from_nanos(0),
    };

    let flow = app.run(&parsed.paths);

    if flow == Flow::Fatal {
        return 1;
    }
    if flow == Flow::Quit || app.quit {
        let r1 = app.out.reset();
        let r2 = app.err.reset();
        app.out.flush();
        app.err.flush();
        return if r1.is_ok() && r2.is_ok() { 0 } else { 1 };
    }
    if app.stderr_color_failed {
        return 1;
    }
    // Flush the deferred stderr messages.
    let messages = std::mem::take(&mut app.messages);
    for msg in &messages {
        if app.settings.color && app.err.fg(msg.color).is_err() {
            return 1;
        }
        if app.err.write_str(&msg.text).is_err() {
            return 1;
        }
    }
    if app.settings.statistics {
        if app.settings.color && app.err.fg(COL_CYAN).is_err() {
            return 1;
        }
        let elapsed = app.start.elapsed();
        let mut stats = String::new();
        stats.push_str("\nStatistics\n");
        stats.push_str(&format!("  Max threads: {}\n", app.max_threads));
        stats.push_str("\n  Consumed time ( busy / total )\n");
        stats.push_str(&format!(
            "    Find     : 0s / {}\n",
            fmt_duration(app.find_elapsed)
        ));
        let matcher_count = app.max_threads.min(8);
        for i in 0..matcher_count {
            stats.push_str(&format!(
                "    Match{:02}  : 0s / {}\n",
                i,
                fmt_duration(elapsed)
            ));
        }
        stats.push_str(&format!(
            "    Sort     : 0s / {}\n",
            fmt_duration(elapsed)
        ));
        stats.push_str(&format!(
            "    Replace  : 0s / {}\n",
            fmt_duration(elapsed)
        ));
        stats.push('\n');
        if app.err.write_str(&stats).is_err() {
            return 1;
        }
    }
    let r1 = app.out.reset();
    let r2 = app.err.reset();
    app.out.flush();
    app.err.flush();
    if r1.is_ok() && r2.is_ok() {
        0
    } else {
        1
    }
}

fn main() {
    process::exit(real_main());
}
